function VerifiedBadge({size=16}:{size?:number}){return <BadgeCheck size={size} fill="var(--accent)" stroke="var(--surface)" strokeWidth={2.8} className="verified-badge" aria-label="Verified"/>}

function MemoProfile({avatarColor,onBack}:{avatarColor:string;onBack:()=>void}){const Avatar=useMemo(()=>createAvatar({...strobiDefinition,colors:{...strobiDefinition.colors,body:avatarColor}}),[avatarColor]);return <section className="profile-view memo-public-profile"><div className="memo-public-banner" style={{background:`linear-gradient(125deg,color-mix(in srgb,${avatarColor} 40%,#111827),${avatarColor} 55%,color-mix(in srgb,${avatarColor} 65%,#ffffff))`}}></div><div className="profile-main"><div className="profile-heading-row"><div className="memo-profile-real-avatar"><Avatar size="92px" ariaLabel="Memo's avatar"/></div><button className="profile-edit-button" onClick={onBack}>Back to Memo</button></div><div className="profile-fields"><strong className="profile-name-display">Memo <VerifiedBadge size={18}/></strong><span className="profile-handle-display">@memo</span><p className="profile-bio">Your AI companion. Here to help you revisit memories, connect ideas, and make sense of the things you write.</p><div className="profile-stats"><strong>0 <span>Posts</span></strong><strong>0 <span>Following</span></strong><strong>0 <span>Followers</span></strong></div></div><div className="profile-tabs"><button className="active">Posts</button></div><div className="profile-feed"><article className="profile-post"><div className="memo-profile-post-avatar"><Avatar size="38px" ariaLabel="Memo's avatar"/></div><div className="post-content"><div className="post-byline"><strong>Memo <VerifiedBadge size={14}/></strong><span>@memo</span><i>·</i><time>just now</time></div><h3>A little space to think.</h3><div className="post-body"><p>I’m here to help you explore your journal, find connections between entries, and prepare edits for your approval. My chat is still being built.</p></div></div></article></div></div></section>}

function MemoScreen({memoText,setMemoText,avatarColor,onOpenProfile}:{memoText:string;setMemoText:(v:string)=>void;avatarColor:string;onOpenProfile:()=>void}){
 const [rotation,setRotation]=useState({x:0,y:0,z:0})
 const Avatar=useMemo(()=>createAvatar({...strobiDefinition,colors:{...strobiDefinition.colors,body:avatarColor}}),[avatarColor])
 const avatarStyle={transform:`perspective(700px) rotateX(${rotation.x}deg) rotateY(${rotation.y}deg) rotateZ(${rotation.z}deg)`} as ReactCSSProperties
 return <section className="memo-view"><div className="memo-profile-link" onClick={onOpenProfile} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==="Enter"||e.key===" ")onOpenProfile()}}><div className="memo-profile-avatar"><Avatar size="38px" ariaLabel="Memo avatar"/></div><div><strong>Memo <VerifiedBadge size={14}/></strong><span>@memo · AI companion</span></div><button onClick={e=>{e.stopPropagation();onOpenProfile()}}>View profile <ArrowUpRight size={13}/></button></div><div className="memo-heading"><div className="eyebrow"><Sparkles size={14}/> YOUR AI COMPANION</div><h1>What’s on your mind?</h1><p>Memo will search your archive, help you reflect, and prepare changes for your approval.</p></div><div className="memo-avatar-stage" onPointerMove={e=>{const r=e.currentTarget.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;setRotation({x:-y*24,y:x*24,z:x*10})}} onPointerLeave={()=>setRotation({x:0,y:0,z:0})}><Avatar className="memo-strobi" animation="idle" size="min(42vw, 210px)" ariaLabel="Strobi, Memo's avatar" style={avatarStyle}/><strong>Memo</strong><span>Your AI companion</span></div><div className="memo-empty"><div className="sparkle-large"><Sparkles size={24}/></div><strong>Memo is not connected yet</strong><span>Chat and AI features aren't connected yet. Strobi is here while we build the rest.</span></div><div className="memo-composer"><button className="memo-add-button" aria-label="Add attachment" title="Add attachment" disabled><Plus size={19}/></button><input value={memoText} onChange={e=>setMemoText(e.target.value)} placeholder="Message Memo…"/><button className="memo-send-button" aria-label={memoText.trim()?"Send message":"Voice message"} title={memoText.trim()?"Send message":"Voice message"} disabled><>{memoText.trim()?<ArrowUp size={19}/>:<AudioLines size={19}/>}</></button></div><p className="fine-print">AI and reviewed editing tools are planned for a later milestone.</p></section>
}

type Attachment = { id:string; name:string; type:string; size:number }
type Entry = { id:number; title:string; date:string; body:string; tags:string[]; importedBatch?:string; attachments?:Attachment[]; folderId?:string; bookmarked?:boolean; createdAt?:number; draft?:boolean }
const attachmentDB=()=>new Promise<IDBDatabase>((resolve,reject)=>{const req=indexedDB.open('memento-attachments',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})
const storeAttachment=async(id:string,file:File)=>{const db=await attachmentDB();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
const readAttachment=async(id:string)=>{const db=await attachmentDB();return new Promise<Blob|null>((resolve,reject)=>{const req=db.transaction('files').objectStore('files').get(id);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)})}
const deleteAttachment=async(id:string)=>{const db=await attachmentDB();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
